from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    if not elf.has_dwarf_info():
        print('No DWARF')
        exit(1)

    dwarf = elf.get_dwarf_info()

    for addr in [0x2f4b20, 0x2f4c84]:
        # Use aranges or line program
        for CU in dwarf.iter_CUs():
            line_program = dwarf.line_program_for_CU(CU)
            if line_program is None:
                continue
            prev_state = None
            for entry in line_program.get_entries():
                if entry.state is None:
                    continue
                if prev_state and not prev_state.end_sequence:
                    if prev_state.address <= addr < entry.state.address:
                        lp_header = line_program.header
                        file_entry = lp_header['file_entry'][prev_state.file - 1]
                        print(f'0x{addr:x} => {file_entry.name.decode()}:{prev_state.line}')
                        break
                prev_state = entry.state
            else:
                continue
            break
        else:
            print(f'0x{addr:x} => no DWARF line info found')
" 2>&1 | head -20

