from elftools.elf.elffile import ELFFile
from elftools.dwarf.callframe import CIE, FDE

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    eh_frame = elf.get_section_by_name('.eh_frame')
    if eh_frame:
        # Parse eh_frame for FDEs covering our addresses
        from elftools.dwarf.callframe import CallFrameInfo
        cfi = CallFrameInfo(eh_frame.stream, eh_frame.data_size, elf.structs, for_eh_frame=True)
        for entry in cfi:
            if hasattr(entry, 'header') and 'initial_location' in entry.header:
                start = entry.header['initial_location']
                size = entry.header.get('address_range', 0)
                end = start + size
                for addr in [0x2f4b20, 0x2f4c84]:
                    if start <= addr < end:
                        print(f'0x{addr:x} in FDE: 0x{start:x}-0x{end:x} (size=0x{size:x})')
" 2>&1 | head -5", "description": "Check .eh_frame for function boundaries", "initial_wait": 60}

